def minPath(grid, k):
    """
    Find the lexicographically minimal path of length k in a grid.
    """
    if k == 0:
        return []

    n = len(grid)
    N = n * n
    values = [grid[i // n][i % n] for i in range(N)]

    # Precompute neighbor indices for each cell
    neighbors = [[] for _ in range(N)]
    for r in range(n):
        for c in range(n):
            idx = r * n + c
            if r > 0:      neighbors[idx].append((r - 1) * n + c)
            if r < n - 1:  neighbors[idx].append((r + 1) * n + c)
            if c > 0:      neighbors[idx].append(r * n + (c - 1))
            if c < n - 1:  neighbors[idx].append(r * n + (c + 1))

    # dp_prev holds minimal suffixes for paths of current length
    dp_prev = [tuple([values[i]]) for i in range(N)]

    for length in range(2, k + 1):
        dp_curr = [None] * N
        for pos in range(N):
            best = None
            val_prefix = values[pos]
            for nb in neighbors[pos]:
                candidate = (val_prefix,) + dp_prev[nb]
                if best is None or candidate < best:
                    best = candidate
            dp_curr[pos] = best
        dp_prev = dp_curr

    # Result: minimal path among all starting cells
    best_path = min(dp_prev)
    return list(best_path)
