def is_simple_power(x, n):
    """
    Return True if x is an integer power of n (i.e. there exists an integer k >= 0
    such that n**k == x), otherwise False.
    """
    # Handle the trivial case first
    if x == 1:
        return True  # n**0 == 1 for any n (except the undefined 0**0 case)

    # Special cases for base n
    if n == 0:
        return x == 0  # 0**k == 0 for any k > 0
    if n == 1:
        return x == 1  # 1**k == 1
    if n == -1:
        return x == 1 or x == -1  # powers alternate between 1 and -1

    # General case: iterate powers of n
    current = 1
    while abs(current) <= abs(x):
        current *= n
        if current == x:
            return True
    return False
