from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        """
        For each group value, find the smallest element index j such that
        group[i] % elements[j] == 0. Elements can be reused across groups.
        """
        if not groups:
            return []

        max_val = max(groups)
        # Map each group value to the list of indices that have that value
        value_to_indices = [[] for _ in range(max_val + 1)]
        for idx, val in enumerate(groups):
            value_to_indices[val].append(idx)

        assigned = [-1] * len(groups)

        # Iterate elements in order of increasing index
        for j, e in enumerate(elements):
            # For every multiple of e up to max_val, assign to unassigned groups
            for mult in range(e, max_val + 1, e):
                for idx in value_to_indices[mult]:
                    if assigned[idx] == -1:
                        assigned[idx] = j

        return assigned
```
This solution runs in \(O\!\left(\sum_{e \in \text{elements}}\frac{\max(\text{groups})}{e}\right)\), which is well below the limits for the given constraints.

