# Solution to the problem: check if a sequence A has at least two distinct subsequences equal to B
import sys

def solve() -> None:
    it = iter(map(int, sys.stdin.read().strip().split()))
    try:
        N = next(it)
        M = next(it)
    except StopIteration:
        return
    A = [next(it) for _ in range(N)]
    B = [next(it) for _ in range(M)]

    earliest = [None] * M
    pos = 0
    for idx, val in enumerate(A):
        if pos < M and val == B[pos]:
            earliest[pos] = idx
            pos += 1
            if pos == M:
                break

    if pos != M:          # B is not a subsequence at all
        print("No")
        return

    latest = [None] * M
    pos = M - 1
    for idx in range(N - 1, -1, -1):
        if pos >= 0 and A[idx] == B[pos]:
            latest[pos] = idx
            pos -= 1
            if pos < 0:
                break

    # Check for any position where earliest < latest
    for i in range(M):
        if earliest[i] is not None and latest[i] is not None and earliest[i] < latest[i]:
            print("Yes")
            return
    print("No")

if __name__ == "__main__":
    solve()
