from typing import List
import functools

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)

        @functools.lru_cache(maxsize=None)
        def dfs(i: int, j: int, k: int) -> int:
            """
            i : current smallest index still present
            j : 1 if element i+1 is still present, 0 otherwise
            k : 1 if element i+2 is still present, 0 otherwise
            """
            # Build list of present indices (must be < n)
            indices = [i]
            if j and i + 1 < n:
                indices.append(i + 1)
            if k and i + 2 < n:
                indices.append(i + 2)

            # No elements left
            if not indices:
                return 0
            # Only one element left – it must be removed in a single op
            if len(indices) == 1:
                return nums[indices[0]]

            best = float('inf')
            # Try all possible pairs to remove
            for a_idx in range(len(indices)):
                for b_idx in range(a_idx + 1, len(indices)):
                    a = indices[a_idx]
                    b = indices[b_idx]
                    pair_cost = max(nums[a], nums[b])

                    removed = {a, b}

                    # Remaining elements of the current window
                    remaining = [x for x in (i, i + 1, i + 2)
                                  if x < n and x not in removed]

                    if not remaining:
                        new_cur = i + 3          # window is empty → jump forward
                    else:
                        new_cur = min(remaining)   # smallest remaining becomes new front

                    # Determine flags for the next window
                    new_j = 0
                    new_k = 0
                    if new_cur < n:
                        if new_cur + 1 < n and (new_cur + 1 not in removed):
                            new_j = 1
                        if new_cur + 2 < n and (new_cur + 2 not in removed):
                            new_k = 1

                    total = pair_cost + dfs(new_cur, new_j, new_k)
                    if total < best:
                        best = total

            return best

        # Initially, indices 0,1,2 (if they exist) are present
        j0 = 1 if n > 1 else 0
        k0 = 1 if n > 2 else 0
        return dfs(0, j0, k0)
